<template>
  <main class="attendance">
    <header class="page-head">
      <div><span>OPERASIONAL HARI INI</span><h1>Absensi berjamaah</h1><p>Catat kehadiran anggota dengan QR dalam satu alur yang ringkas.</p></div>
      <button class="active-session" @click="sessionDialog = true"><i></i><span><small>SESI AKTIF</small><strong>{{ activeSession.name }}</strong></span><q-icon name="expand_more" /></button>
    </header>

    <nav class="tabs" aria-label="Menu absensi">
      <button v-for="tab in tabs" :key="tab.id" :class="{ active: view === tab.id }" @click="view = tab.id"><q-icon :name="tab.icon" />{{ tab.label }}<b v-if="tab.id === 'scanner'">{{ attendance.length }}</b></button>
    </nav>

    <section v-if="view === 'scanner'" class="scanner-grid">
      <article class="card scanner-card">
        <div class="card-top"><span><i></i> SCANNER PENGAJAR</span><button @click="toggleCamera"><q-icon :name="cameraOn ? 'videocam_off' : 'videocam'" /> {{ cameraOn ? 'Matikan kamera' : 'Aktifkan kamera' }}</button></div>
        <div class="camera">
          <video ref="videoEl" :class="{ visible: cameraOn }" muted playsinline></video>
          <div class="corners"><i></i><i></i><i></i><i></i><b></b></div>
          <div v-if="!cameraOn" class="camera-empty"><q-icon name="qr_code_scanner" /><strong>Kamera belum aktif</strong><span>Arahkan kamera ke QR anggota</span><button @click="toggleCamera">Mulai memindai</button></div>
        </div>
        <div class="manual"><span>Atau masukkan ID anggota</span><div><q-input v-model="manualCode" outlined dense placeholder="Contoh: AGT-001" @keyup.enter="manualCheckin"><template #prepend><q-icon name="badge" /></template></q-input><q-btn unelevated no-caps label="Catat hadir" @click="manualCheckin" /></div></div>
      </article>

      <aside class="card attendance-card">
        <div class="presence-head"><span><small>HADIR SAAT INI</small><strong>{{ attendance.length }} anggota</strong></span><q-icon name="groups" /></div>
        <div class="progress"><span>Kapasitas sesi</span><strong>{{ Math.round(attendance.length / 40 * 100) }}%</strong></div><q-linear-progress rounded size="6px" :value="attendance.length / 40" color="positive" track-color="grey-3" />
        <h3>BARU SAJA HADIR</h3>
        <div v-if="attendance.length" class="recent"><div v-for="item in attendance.slice(0, 5)" :key="item.id"><i>{{ initials(item.name) }}</i><span><strong>{{ item.name }}</strong><small>{{ item.role }} · {{ item.time }}</small></span><q-icon name="check_circle" /></div></div>
        <div v-else class="empty">Belum ada anggota yang dipindai.</div>
        <button class="report-link" @click="view = 'rekap'">Lihat semua kehadiran <q-icon name="arrow_forward" /></button>
      </aside>
    </section>

    <section v-else-if="view === 'sesi'" class="card panel">
      <div class="panel-head"><div><span>MANAJEMEN SESI</span><h2>Sesi sholat hari ini</h2></div><q-btn unelevated no-caps icon="add" label="Pilih sesi" @click="sessionDialog = true" /></div>
      <div class="session-grid"><button v-for="session in sessions" :key="session.id" :class="{ active: activeSession.id === session.id }" @click="selectSession(session)"><q-icon :name="session.icon" /><span><strong>{{ session.name }}</strong><small>{{ session.time }} · Ruang utama</small></span><em>{{ activeSession.id === session.id ? 'Aktif' : 'Pilih' }}</em></button></div>
    </section>

    <section v-else-if="view === 'qr'" class="card panel">
      <div class="panel-head"><div><span>IDENTITAS ANGGOTA</span><h2>QR anggota</h2><p>Cari anggota lalu tampilkan kartu QR untuk dipindai pengajar.</p></div></div>
      <q-input v-model="search" class="search" outlined dense clearable placeholder="Cari nama atau ID anggota"><template #prepend><q-icon name="search" /></template></q-input>
      <div class="member-grid"><article v-for="member in filteredMembers" :key="member.id"><div class="person"><i>{{ initials(member.name) }}</i><span><strong>{{ member.name }}</strong><small>{{ member.id }} · {{ member.role }}</small></span></div><img :src="qrUrl(member.id)" :alt="`QR ${member.name}`"><button @click="downloadQr(member)"><q-icon name="download" /> Unduh QR</button></article></div>
    </section>

    <section v-else class="card panel report">
      <div class="panel-head"><div><span>REKAP KEHADIRAN</span><h2>{{ activeSession.name }} · hari ini</h2></div><q-btn outline no-caps icon="download" label="Unduh CSV" @click="downloadCsv" /></div>
      <div class="summaries"><div><q-icon name="groups" /><span>Total hadir<strong>{{ attendance.length }}</strong></span></div><div><q-icon name="schedule" /><span>Tepat waktu<strong>{{ onTimeCount }}</strong></span></div><div><q-icon name="trending_up" /><span>Tingkat hadir<strong>{{ attendanceRate }}%</strong></span></div></div>
      <div class="table-wrap"><table><thead><tr><th>Anggota</th><th>ID</th><th>Peran</th><th>Waktu</th><th>Status</th></tr></thead><tbody><tr v-for="item in attendance" :key="item.id"><td><span class="table-person"><i>{{ initials(item.name) }}</i>{{ item.name }}</span></td><td>{{ item.id }}</td><td>{{ item.role }}</td><td>{{ item.time }}</td><td><b>Hadir</b></td></tr><tr v-if="!attendance.length"><td colspan="5" class="empty">Belum ada data kehadiran.</td></tr></tbody></table></div>
    </section>

    <q-dialog v-model="sessionDialog"><q-card class="dialog"><q-card-section><span class="eyebrow">SESI SHOLAT</span><h2>Pilih sesi aktif</h2></q-card-section><q-card-section class="dialog-list"><button v-for="session in sessions" :key="session.id" :class="{ active: activeSession.id === session.id }" @click="selectSession(session)"><q-icon :name="session.icon" /><span><strong>{{ session.name }}</strong><small>{{ session.time }}</small></span><q-icon name="check_circle" /></button></q-card-section></q-card></q-dialog>
  </main>
</template>

<script setup>
import { computed, onBeforeUnmount, ref } from 'vue'
import { useQuasar } from 'quasar'

defineProps({ profile: { type: Object, required: true } })
const $q = useQuasar()
const tabs = [{ id: 'scanner', label: 'Scanner', icon: 'qr_code_scanner' }, { id: 'sesi', label: 'Sesi sholat', icon: 'event' }, { id: 'qr', label: 'QR anggota', icon: 'badge' }, { id: 'rekap', label: 'Rekap', icon: 'analytics' }]
const sessions = [{ id: 'subuh', name: 'Sholat Subuh', time: '04.37–05.10', icon: 'wb_twilight' }, { id: 'dzuhur', name: 'Sholat Dzuhur', time: '11.48–12.25', icon: 'light_mode' }, { id: 'ashar', name: 'Sholat Ashar', time: '15.08–15.40', icon: 'sunny_snowing' }, { id: 'maghrib', name: 'Sholat Maghrib', time: '17.51–18.20', icon: 'nights_stay' }, { id: 'isya', name: 'Sholat Isya', time: '19.00–19.35', icon: 'dark_mode' }]
const members = [{ id: 'AGT-001', name: 'Ahmad Fauzan', role: 'Pengajar' }, { id: 'AGT-002', name: 'Muhammad Rizky', role: 'Murid' }, { id: 'AGT-003', name: 'Naila Humaira', role: 'Murid' }, { id: 'AGT-004', name: 'Siti Aisyah', role: 'Pengajar' }, { id: 'AGT-005', name: 'Faris Alwi', role: 'Murid' }, { id: 'AGT-006', name: 'Zahra Rahmani', role: 'Murid' }]
const view = ref('scanner'), activeSession = ref(sessions[1]), sessionDialog = ref(false), search = ref(''), manualCode = ref(''), cameraOn = ref(false), videoEl = ref(null)
const saved = JSON.parse(localStorage.getItem('dkm-attendance') || '[]')
const attendance = ref(saved.length ? saved : [{ ...members[0], time: '11:51' }, { ...members[2], time: '11:54' }, { ...members[1], time: '11:56' }])
let stream, scanTimer
const filteredMembers = computed(() => { const query = search.value?.toLowerCase() || ''; return members.filter((member) => `${member.id} ${member.name}`.toLowerCase().includes(query)) })
const onTimeCount = computed(() => attendance.value.filter((item) => item.time <= '12:00').length)
const attendanceRate = computed(() => Math.round(attendance.value.length / members.length * 100))
const initials = (name) => name.split(' ').slice(0, 2).map((part) => part[0]).join('')
const qrUrl = (id) => `https://api.qrserver.com/v1/create-qr-code/?size=180x180&margin=10&data=${encodeURIComponent(`DKM:${id}`)}`
function checkin(value) { const code = value.replace('DKM:', '').trim().toUpperCase(); const member = members.find((item) => item.id === code); if (!member) return notify('negative', 'QR anggota tidak dikenali.'); if (attendance.value.some((item) => item.id === code)) return notify('warning', `${member.name} sudah tercatat hadir.`); attendance.value.unshift({ ...member, time: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }).replace('.', ':') }); localStorage.setItem('dkm-attendance', JSON.stringify(attendance.value)); notify('positive', `${member.name} berhasil dicatat hadir.`) }
function notify(type, message) { $q.notify({ type, message, position: 'top' }) }
function manualCheckin() { if (manualCode.value) checkin(manualCode.value); manualCode.value = '' }
async function toggleCamera() { if (cameraOn.value) return stopCamera(); try { stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); cameraOn.value = true; setTimeout(() => { videoEl.value.srcObject = stream; videoEl.value.play(); detectCodes() }) } catch { notify('negative', 'Kamera tidak dapat diakses. Gunakan ID anggota.') } }
async function detectCodes() { if (!('BarcodeDetector' in window)) return; const detector = new BarcodeDetector({ formats: ['qr_code'] }); scanTimer = setInterval(async () => { if (!videoEl.value?.readyState) return; try { const codes = await detector.detect(videoEl.value); if (codes[0]) checkin(codes[0].rawValue) } catch {} }, 700) }
function stopCamera() { clearInterval(scanTimer); stream?.getTracks().forEach((track) => track.stop()); cameraOn.value = false }
function selectSession(session) { activeSession.value = session; sessionDialog.value = false }
async function downloadQr(member) { const response = await fetch(qrUrl(member.id)); const blob = await response.blob(); downloadBlob(blob, `QR-${member.id}.png`) }
function downloadCsv() { const rows = [['Nama', 'ID', 'Peran', 'Waktu', 'Status'], ...attendance.value.map((item) => [item.name, item.id, item.role, item.time, 'Hadir'])]; downloadBlob(new Blob([rows.map((row) => row.join(',')).join('\n')], { type: 'text/csv' }), `rekap-${activeSession.value.id}.csv`) }
function downloadBlob(blob, name) { const anchor = document.createElement('a'); anchor.href = URL.createObjectURL(blob); anchor.download = name; anchor.click(); URL.revokeObjectURL(anchor.href) }
onBeforeUnmount(stopCamera)
</script>

