city:0}.camera video.visible{opacity:1}.camera-empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#fff;background:radial-gradient(circle at 50% 30%,#214c3f,#10251f 70%)}.camera-empty>.q-icon{font-size:62px;color:#8fc7b6}.camera-empty strong{margin-top:14px}.camera-empty span{margin-top:5px;color:#9eb0aa;font-size:11px}.camera-empty button{margin-top:18px;padding:10px 18px;border:0;border-radius:9px;color:#0d5544;background:#fff;font-weight:700;cursor:pointer}.corners{position:absolute;top:50%;left:50%;width:210px;height:210px;transform:translate(-50%,-50%);pointer-events:none}.camera:has(.camera-empty) .corners{display:none}.corners i{position:absolute;width:34px;height:34px;border-color:#e6c86f;border-style:solid}.corners i:nth-child(1){border-width:3px 0 0 3px}.corners i:nth-child(2){right:0;border-width:3px 3px 0 0}.corners i:nth-child(3){bottom:0;border-width:0 0 3px 3px}.corners i:nth-child(4){right:0;bottom:0;border-width:0 3px 3px 0}.corners b{position:absolute;top:50%;width:100%;height:2px;background:#e6c86f;animation:scan 2s ease-in-out infinite}.manual{margin-top:15px}.manual>span{display:block;margin-bottom:7px;color:#7d8c87;font-size:10px}.manual>div{display:flex;gap:8px}.manual .q-input{flex:1}.manual .q-btn,.panel-head .q-btn{border-radius:9px;color:#fff;background:#116b54;font-size:11px}.attendance-card{padding:20px}.presence-head{display:flex;align-items:center;justify-content:space-between;padding-bottom:16px;border-bottom:1px solid #ecf0ee}.presence-head>span{display:flex;flex-direction:column}.presence-head small,.attendance-card h3{color:#899792;font-size:9px;font-weight:800;letter-spacing:1.2px}.presence-head strong{margin-top:3px;font-size:19px}.presence-head>.q-icon{font-size:28px;color:#19836a}.progress{display:flex;justify-content:space-between;margin:16px 0 7px;color:#83918c;font-size:10px}.attendance-card h3{margin:22px 0 11px}.recent>div{display:flex;align-items:center;gap:9p